def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    weak_prev = []

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= DAILY_SALARY * 0.9:
                    strong_prev.append(float(bid))
                else:
                    weak_prev.append(float(bid))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    total_players = 1 + len(alive)
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < total_players

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if scarcity:
        urgency += 2
    if float(supply) <= 17:
        urgency += 1
    elif float(supply) >= 23:
        urgency -= 1

    base = DAILY_SALARY * 0.42

    if urgency >= 6:
        target = max(DAILY_SALARY * 0.98, highest_prev + 2.5)
    elif urgency >= 4:
        if highest_prev > 0:
            target = max(DAILY_SALARY * 0.78, highest_prev + 1.25)
        else:
            target = DAILY_SALARY * 0.82
    elif urgency >= 2:
        if scarcity and highest_prev > 0:
            target = max(DAILY_SALARY * 0.62, min(highest_prev + 0.75, DAILY_SALARY * 0.9))
        else:
            target = max(base, avg_prev * 0.78 if avg_prev > 0 else DAILY_SALARY * 0.52)
    else:
        if len(strong_prev) >= 2:
            target = DAILY_SALARY * 0.28
        elif highest_prev >= DAILY_SALARY * 0.9:
            target = DAILY_SALARY * 0.33
        elif scarcity and highest_prev > 0:
            target = max(DAILY_SALARY * 0.48, second_prev + 0.5)
        else:
            target = DAILY_SALARY * 0.4

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0 and urgency < 4:
        soft_cap = min(soft_cap, budget / max(1, reserve_days // 2 + 1) + DAILY_SALARY * 0.25)

    if hp <= 2 or no_water_days >= 2:
        soft_cap = budget

    bid = min(target, soft_cap, budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, conserve.
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction).
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate how aggressive the field was.
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: lower supply tends to require stronger bids.
    # Normalize into [0,1] where 1 = tightest.
    if MAX_SUPPLY > MIN_SUPPLY:
        tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    else:
        tightness = 0.5
    tightness = max(0.0, min(1.0, tightness))

    # Base bid: aim below the leaders to avoid overpaying.
    # If leaders were very aggressive (high highest_prev_bid), increase slightly.
    leader_signal = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        leader_signal = 0.25
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        leader_signal = 0.15
    else:
        leader_signal = 0.05

    # Need-based escalation.
    if hp <= 2 or no_water_days >= 1:
        need_mult = 0.95
    elif hp <= 3:
        need_mult = 0.75
    else:
        need_mult = 0.55

    # Compute target bid.
    # Use a blend of supply tightness and leader signal, but keep under leader bids.
    target = DAILY_SALARY * (need_mult + leader_signal) * (0.65 + 0.35 * tightness)

    # If yesterday bids were known, cap relative to average/highest to stay exploitative.
    if avg_prev_bid > 0:
        target = min(target, avg_prev_bid * 0.95)
    if highest_prev_bid > 0:
        target = min(target, highest_prev_bid * 0.85)

    # Ensure non-negative and within budget.
    bid = max(0.0, min(budget, target))

    # If budget is tiny, still bid something to avoid wasting the day.
    if bid < 1e-6 and budget > 0:
        bid = min(budget, 1.0)

    return bid

